// @vitest-environment node
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import Ajv from 'ajv';
import { demoDevice } from '../device';
import { statusDocument } from '../handlers';
import { mockWifiNetworks } from '../../mocks/data';

// Every document the demo answers must match the device's contract
// (specs/001-platform-bootstrap/contracts/schemas, generated by
// tools/contracts/generate_schemas.py from this demo's samples until a real
// RoofRoof exists). A field the device doesn't send, or a missing one, fails here.
// CONTRACT_SAMPLES=<dir> writes those samples:
//   CONTRACT_SAMPLES=/tmp/samples npx vitest run contracts && python3 tools/contracts/generate_schemas.py /tmp/samples

const files = import.meta.glob('../../../../specs/001-platform-bootstrap/contracts/schemas/*.schema.json', {
  eager: true,
  import: 'default',
});
const ajv = new Ajv({ allErrors: true, strict: false });
const schemas: Record<string, object> = Object.fromEntries(
  Object.entries(files).map(([path, schema]) => [path.split('/').pop()!.replace('.schema.json', ''), schema as object]),
);

const check = (schemaName: string, document: unknown) => {
  const validate = ajv.compile(schemas[schemaName]);
  const ok = validate(document);
  expect(ok, `${schemaName}: ${ajv.errorsText(validate.errors, { separator: '\n' })}`).toBe(true);
};

const alpaca = (path: string) => JSON.parse(demoDevice.alpaca('GET', path, []).body);

// The samples the schema generator reads (<source>-<document>.json). Several
// states of the one emulated device, so optional values (a set "since", alerts
// in the list) show up. There is no Alpaca device yet, so the client-state
// sample is the firmware's writeClientWatch (lib/DeviceCore/src/DeviceAlerts.cpp)
// applied by hand to a "dome" device.
function writeSamples(dir: string) {
  mkdirSync(dir, { recursive: true });
  const put = (name: string, document: unknown) => writeFileSync(join(dir, `${name}.json`), JSON.stringify(document, null, 2) + '\n');
  const status = (alerts?: object, clients?: Record<string, object>, roof?: object) => {
    const s = statusDocument() as unknown as { alerts: object; alpaca: { clients: object }; roof: object };
    return {
      ...s,
      alerts: { ...s.alerts, ...alerts },
      alpaca: { ...s.alpaca, clients: clients ?? s.alpaca.clients },
      roof: { ...s.roof, ...roof },
    };
  };
  const base = status();
  put('device-status', base);
  put(
    'device2-status',
    status(
      { since: '2026-11-10T12:00:00Z', sinceAgeMs: 1000 },
      { dome: { connected: true, watching: true, silent: false, lastCheckedAgeMs: 1500, clientId: 1234 } },
      // The roof opening part-way with current sense on (src/RoofControl, lib/RoofIoLogic writeStatus).
      {
        state: 'opening',
        positionMm: 463,
        positionPercent: 25,
        target: 'open',
        driving: true,
        moveElapsedMs: 12000,
        moveTimeoutMs: 66000,
        hall: { level: 'between', counts: 2010 },
        currentSense: true,
        motorAmps: 4.26,
        parkSwitches: { fitted: 2, switch1: 'open', switch2: 'unreadable' },
        rainContact: 'dry',
        closePending: true,
      },
    ),
  );
  put(
    'device3-status',
    status(
      undefined,
      { dome: { connected: false, watching: false, silent: false, lastCheckedAgeMs: null, clientId: null } },
      // A latched fault: position unknown, the supply unreadable.
      {
        state: 'error',
        positionKnown: false,
        positionMm: null,
        positionPercent: null,
        hall: { level: 'unsettled', counts: 0 },
        supplyVolts: null,
        supplyLow: true,
        parkSwitches: { fitted: 1, switch1: 'closed', switch2: 'notFitted' },
        rainContact: 'raining',
        fault: { kind: 'external', cause: 'watchdog', measured: 140, limit: 100, text: 'Control step 140 ms late > 100 ms (watchdog)' },
        watchdogTrips: 1,
      },
    ),
  );
  put('demo-settings_effective', JSON.parse(demoDevice.effective()));
  put('demo-config', JSON.parse(demoDevice.getConfig()));
  put('demo-alerts_armed', JSON.parse(demoDevice.armedDocument()));
  demoDevice.testAlert({ channel: 'all' });
  put('demo-alerts_recent', JSON.parse(demoDevice.recentAlerts()));
  demoDevice.setArmed(false, 'ui');
  put('demo2-alerts_armed', JSON.parse(demoDevice.armedDocument()));
  demoDevice.setArmed(true, 'ui');
  put('demo-management_v1_description', alpaca('/management/v1/description'));
  put('demo-management_v1_configureddevices', alpaca('/management/v1/configureddevices'));
}

describe('demo documents match the device contract', () => {
  beforeAll(async () => {
    await demoDevice.start();
    await new Promise((resolve) => setTimeout(resolve, 2100)); // a couple of ticks
  });
  afterAll(() => demoDevice.stop());

  it.runIf(process.env.CONTRACT_SAMPLES)('writes the schema generator samples', () => writeSamples(process.env.CONTRACT_SAMPLES!));

  it('status (/api/status, /ws/status)', () => check('status', statusDocument()));
  it('settings in effect', () => check('settings-effective', JSON.parse(demoDevice.effective())));
  it('config', () => check('config', JSON.parse(demoDevice.getConfig())));
  it('recent alerts', () => check('alerts-recent', JSON.parse(demoDevice.recentAlerts())));
  it('alerts sending or paused (/api/alerts/armed)', () => check('alerts-armed', JSON.parse(demoDevice.armedDocument())));
  it('WiFi scan', () => {
    check('wifi-scan', { success: true, scanning: false, networks: mockWifiNetworks });
  });
  it('Alpaca management', () => {
    check('alpaca-description', alpaca('/management/v1/description'));
    check('alpaca-configured-devices', alpaca('/management/v1/configureddevices'));
  });

  it('a field the device does not send fails the check', () => {
    const status = statusDocument() as Record<string, unknown>;
    status.upTime = status.uptime; // e.g. a rename that drifted
    const validate = ajv.compile(schemas.status);
    expect(validate(status)).toBe(false);
  });
});
